    const panel=el('div','de-panel');panel.id='de-result-panel';
    const filter=el('button','de-filter','Nur Deutschland');filter.type='button';filter.setAttribute('aria-label','Nur Deutschland');filter.setAttribute('aria-pressed',String(dayEndGermanOnly));filter.setAttribute('aria-controls',panel.id);
    const buttons=new Map();
    for(const [key,[label]] of Object.entries(dayEndMeta)){
      const button=el('button','de-category',label);button.type='button';button.setAttribute('aria-controls',panel.id);button.setAttribute('aria-pressed',String(key===dayEndSelection));
      button.addEventListener('click',()=>{dayEndSelection=key;draw();});buttons.set(key,button);nav.append(button);
    }
    const germanyButton=el('button','de-category','Turnteam Deutschland');germanyButton.type='button';germanyButton.setAttribute('aria-controls',panel.id);germanyButton.setAttribute('aria-pressed','false');germanyButton.addEventListener('click',()=>{dayEndSelection='germany';draw();});buttons.set('germany',germanyButton);nav.append(germanyButton);
    filter.addEventListener('click',()=>{dayEndGermanOnly=!dayEndGermanOnly;draw();});controls.append(nav,filter);wrap.append(controls,panel);
    const announce=el('p','de-sr');announce.setAttribute('role','status');announce.setAttribute('aria-live','polite');wrap.append(announce);
