      sharedFoot.append(el('p','de-explain','Team: Je Gerät zählen die drei höchsten Teamnoten. DNS = nicht gestartet · DNF = Mehrkampf nicht beendet. Sprung-Geräterangliste: zwei Sprünge einschließlich des ausgewiesenen Bonus; für Team und Mehrkampf zählt der erste Sprung.'));
      const sources=el('p','de-explain');sources.append(document.createTextNode('Offizielle Tabellen: '));
