      panel.replaceChildren(...groups,sharedFoot,el('p','de-snapshot','Zwischenstand der laufenden Frauenqualifikation. Geprüft am 19.10.2026 um 20:51 Uhr. Alle Platzierungen sind vorläufig; die Qualifikation endet heute voraussichtlich gegen 22:30 Uhr.'));filter.hidden=true;
