      const foot=el('div','de-table-foot');const checked=new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Amsterdam',hour:'2-digit',minute:'2-digit'}).format(new Date(dayEndData.checkedAt));
      const notes={team:'Je Gerät zählen die drei höchsten Teamnoten.',allaround:'DNS = nicht gestartet · DNF = Mehrkampf nicht beendet.',vault:'Geräterangliste aus zwei Sprüngen, einschließlich des von Longines ausgewiesenen Bonus. Für Team und Mehrkampf zählt der erste Sprung.',bars:'D = Schwierigkeit · E = Ausführung · Abzug = neutraler Abzug.',beam:'D = Schwierigkeit · E = Ausführung · Abzug = neutraler Abzug.',floor:'D = Schwierigkeit · E = Ausführung · Abzug = neutraler Abzug.'};
      const info=el('p','de-explain',notes[dayEndSelection]);const source=el('a','de-source','Offizielle Tabelle ↗');source.href=data.source;source.target='_blank';source.rel='noopener';foot.append(info,source);panel.append(foot,el('p','de-snapshot','Zwischenstand der laufenden Frauenqualifikation. Geprüft am 19.10.2026 um 20:51 Uhr. Alle Platzierungen sind vorläufig; die Qualifikation endet heute voraussichtlich gegen 22:30 Uhr.'));announce.textContent=label+': '+rows.length+' '+noun+' angezeigt.';
